def test_core_packages_exclude_plugins_and_full_only_adds_runtime(self) -> None:
        lite = {path.relative_to(ROOT).as_posix() for path in PACKAGE_RELEASE.source_files(False)}
        full = {path.relative_to(ROOT).as_posix() for path in PACKAGE_RELEASE.source_files(True)}
        self.assertTrue(set(PACKAGE_RELEASE.CORE_REQUIRED_FILES) <= lite)
        self.assertFalse(any(path == "plugins" or path.startswith("plugins/") for path in lite | full))
        self.assertLess(lite, full)
        self.assertTrue(all(path.startswith("assets/runtime/win-x64/") for path in full - lite))

def test_mechanical_fragments_do_not_enter_fts_terms(self) -> None:
        for text, fragment in (
            ("打包不满足", "包不满"),
            ("是否会回", "否会回"),
            ("回的检索", "回的检"),
        ):
            self.assertNotIn(fragment, fts_query_terms(text))
            self.assertNotIn(fragment, search_terms(text))
            self.assertIn(text, search_terms(text))

def test_mixed_camel_identifier_order_is_fixed(self) -> None:
        self.assertEqual(
            search_terms("OrderService 服务修改"),
            ["orderservice", "服务修改", "service", "order", "务修改", "服务修", "修改", "务修", "服务"],
        )
        self.assertEqual(explicit_anchors("OrderService 服务修改"), ["orderservice"])

def _section(markdown: str, heading: str, next_heading: str | None) -> str:
    start = markdown.index(f"## {heading}\n")
    end = len(markdown) if next_heading is None else markdown.index(f"## {next_heading}\n", start + 1)
    return markdown[start:end]

def setUpClass(cls) -> None:
        cls.markdown = README.read_text(encoding="utf-8")
        cls.fixture = json.loads(FIXTURE.read_text(encoding="utf-8"))

def test_required_headings_are_exact_and_ordered(self) -> None:
        headings = re.findall(r"^## (.+)$", self.markdown, flags=re.MULTILINE)
        self.assertEqual(self.fixture["headings"], headings)
